from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np
m=Chem.RWMol(); xy={}; ids={}
def atom(name,element,x,y,z=0,charge=0):
 a=Chem.Atom(element); a.SetFormalCharge(charge); ids[name]=m.AddAtom(a);xy[name]=(x,y,z);return ids[name]
def bond(a,b,t='s'):
 typ={'s':Chem.BondType.SINGLE,'d':Chem.BondType.DOUBLE,'ar':Chem.BondType.AROMATIC,'dat':Chem.BondType.DATIVE}[t];m.AddBond(ids[a],ids[b],typ)
# Origin cobalt at (690,683) -> reference coordinates
atom('Co1','Co',690,685,0);atom('Co2','Co',690,872,-0.3,charge=-1);bond('Co1','Co2')
for name,loc,zz in [('N1',(600,575),-.7),('N2',(721,486),.1),('N3',(855,650),-.1),('N4',(579,698),1.0),('N5',(683,1005),-.2),('N6',(567,1142),-.2)]:atom(name,'N',*loc,zz)
for n in ['N1','N2','N3','N4']:bond(n,'Co1')
bond('Co2','N5','d');bond('N5','N6')
# aryl ortho-diamine ring
r=[('A0',677,357),('A1',797,355),('A2',856,253),('A3',800,151),('A4',682,151),('A5',622,252)]
for name,x,y in r:atom(name,'C',x,y,-.3)
for j in range(6):bond(r[j][0],r[(j+1)%6][0],'ar')
bond('N1','A0');bond('N2','A1')
# ortho methylphenyl group
r=[('B0',484,490),('B1',566,402),('B2',534,290),('B3',422,259),('B4',340,343),('B5',370,456)]
for name,x,y in r:atom(name,'C',x,y,1.4)
for j in range(6):bond(r[j][0],r[(j+1)%6][0],'ar')
bond('N4','B0');atom('BMe','C',632,438,1.6);bond('B1','BMe')
# right aryl N2 to N3
r=[('D0',884,434),('D1',933,329),('D2',1050,314),('D3',1118,410),('D4',1070,518),('D5',952,533)]
for name,x,y in r:atom(name,'C',x,y,-.2)
for j in range(6):bond(r[j][0],r[(j+1)%6][0],'ar')
bond('N2','D0');bond('N3','D5')
# dialkylphosphino groups: upper-left P-N1; lower-left P-CH2-N4; right P-CH2-N3
for p,x,y,z in [('P1',365,553,-1.1),('P2',535,908,1.0),('P3',907,844,-.8)]:atom(p,'P',x,y,z)
bond('P1','N1');atom('CL','C',518,788,1.5);bond('CL','N4');bond('CL','P2');atom('CR','C',952,716,-.4);bond('CR','N3');bond('CR','P3')
# P2 P3 cobalt dative - valid valence P3 and cobalt acceptor
bond('P2','Co2','dat');bond('P3','Co2','dat')
# iPr groups start radial from P, 2 branches each, methyls in different directions
ips=[('P1', (240,487,-1.1),(297,668,-1.3)),('P2',(438,958,1.3),(562,1041,1.0)),('P3',(1040,863,-.8),(955,937,-1.3))]
for p, v1,v2 in ips:
 pxyz=np.array(xy[p],float)
 for i,v in enumerate([v1,v2]):
  x,y,z=v;center=f'{p}i{i}';atom(center,'C',x,y,z);bond(p,center)
  dr=np.array((x,y,z),float)-pxyz; dd=dr[:2]/np.linalg.norm(dr[:2]);perp=np.array([-dd[1],dd[0]])
  for j,side in enumerate([-1,1]):
   pt=np.array([x,y])+dd*95+perp*side*55
   nm=f'{p}m{i}{j}';atom(nm,'C',float(pt[0]),float(pt[1]),z+(.5 if side>0 else -.5));bond(center,nm)
# N6 trimethyl silyl groups; positions near distal N center
for si,x,y,z in [('Si1',441,1212,-.2),('Si2',610,1269,-.5)]:
 atom(si,'Si',x,y,z);bond('N6',si)
 for j,(dx,dy,dz) in enumerate([(-94,45,0),(18,105,.4),(36,-29,-1.1)]):
  nm=si+'Me'+str(j);atom(nm,'C',x+dx,y+dy,z+dz);bond(si,nm)

mol=m.GetMol();
try:Chem.SanitizeMol(mol);print('sanitize yes',Chem.MolToSmiles(mol))
except Exception as e:print('sanitize failure',e)
conf=Chem.Conformer(mol.GetNumAtoms())
for name,k in ids.items():
 x,y,z=xy[name];conf.SetAtomPosition(k,((x-690)*.013,-(y-685)*.013,z))
mol.AddConformer(conf)
Chem.MolToMolFile(mol,'start.mol')
mh=Chem.AddHs(mol,addCoords=True)
print('atoms',len(ids),mh.GetNumAtoms())
from rdkit.Chem import rdForceFieldHelpers
for force in ['UFF','MMFF']:
 try:
  if force=='UFF':print(force,AllChem.UFFHasAllMoleculeParams(mh)); f=AllChem.UFFGetMoleculeForceField(mh,ignoreInterfragInteractions=False)
  else:print(force,AllChem.MMFFHasAllMoleculeParams(mh));f=AllChem.MMFFGetMoleculeForceField(mh,AllChem.MMFFGetMoleculeProperties(mh))
  print('field',f)
 except Exception as e:print('field error',e)
try:
 mh.RemoveAllConformers();par=AllChem.ETKDGv3();par.randomSeed=35;par.maxIterations=800;par.useRandomCoords=True;par.clearConfs=True
 status=AllChem.EmbedMolecule(mh,par);print('embed status',status)
 if status==0:
  conf=mh.GetConformer();pos=conf.GetPositions();np.savetxt('rdkit-embedded.xyz',[],fmt='%s')
  with open('rdkit-embedded.xyz','w') as f:
   f.write(f'{len(pos)}\nRDKit embedded Co compound\n');
   for a,v in zip(mh.GetAtoms(),pos):f.write(f'{a.GetSymbol()} {v[0]:.7f} {v[1]:.7f} {v[2]:.7f}\n')
except Exception as e:print('embed error',e)
